int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, K;
    cin >> H >> W >> K;
    vector<string> grid(H);
    for (int i = 0; i < H; i++) cin >> grid[i];

    queue<pair<int,int>> q;
    vector<vector<int>> dist(H, vector<int>(W, -1));
    int sx = -1, sy = -1;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'S') {
                sx = i; sy = j;
            }
        }
    }

    q.push({sx, sy});
    dist[sx][sy] = 0;

    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};

    // Cells reachable with one cast (moving through only non-# cells up to K steps)
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        if (dist[x][y] == K) continue;
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir], ny = y + dy[dir];
            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            if (grid[nx][ny] == '#') continue;
            if (dist[nx][ny] != -1) continue;
            dist[nx][ny] = dist[x][y] + 1;
            q.push({nx, ny});
        }
    }

    int best = INT_MAX;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (dist[i][j] == -1) continue;

            int d = min({i, H - 1 - i, j, W - 1 - j});
            // Already on border => 1 cast is enough (the first one)
            // Otherwise, after reaching this cell in the first cast,
            // each additional cast can reduce remaining distance to border by up to K.
            int casts = 1 + (d + K - 1) / K;
            best = min(best, casts);
        }
    }

    cout << best << '\n';
    return 0;
}

