            String line = sc.next();
            for (int j = 0; j < W; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') { sr = i; sc2 = j; }
            }
        }
        int[] dr = {-1,1,0,0}, dc = {0,0,-1,1};
        boolean[][] current = new boolean[H][W];
        current[sr][sc2] = true;
        for (int cast = 0; cast <= H*W; cast++) {
            // Check if any current position is on border
            for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) {
                if (current[i][j] && (i==0||i==H-1||j==0||j==W-1)) {
                    System.out.println(cast); return;
                }
            }
            // Expand: from all current positions, find reachable in K moves, K unlocks
            int[][][] minUnlocks = new int[H][W][K+1];
            for (int[][] a : minUnlocks) for (int[] b : a) Arrays.fill(b, Integer.MAX_VALUE);
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a->a[2]));
            for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) if (current[i][j]) {
                if (minUnlocks[i][j][0] > 0) { minUnlocks[i][j][0] = 0; pq.offer(new int[]{i,j,0,0}); }
            }
            boolean[][] next = new boolean[H][W];
            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int r=cur[0],c=cur[1],unlocks=cur[2],moves=cur[3];
                if (unlocks > minUnlocks[r][c][moves]) continue;
                next[r][c] = true;
                if (moves >= K) continue;
                for (int d = 0; d < 4; d++) {
                    int nr=r+dr[d],nc=c+dc[d];
                    if (nr<0||nr>=H||nc<0||nc>=W) continue;
                    int nu = unlocks + (grid[nr][nc]=='#'?1:0);
                    if (nu > K) continue;
                    int nm = moves+1;
                    if (nu < minUnlocks[nr][nc][nm]) { minUnlocks[nr][nc][nm]=nu; pq.offer(new int[]{nr,nc,nu,nm}); }
                }
            }
            current = next;
        }
    }
}

