public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int H = fs.nextInt();
        int W = fs.nextInt();
        int K = fs.nextInt();

        char[][] grid = new char[H][];
        int sx = -1, sy = -1;

        for (int i = 0; i < H; i++) {
            grid[i] = fs.next().toCharArray();
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == 'S') {
                    sx = i;
                    sy = j;
                }
            }
        }

        int[][] dist = new int[H][W];
        for (int i = 0; i < H; i++) Arrays.fill(dist[i], -1);

        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{sx, sy});
        dist[sx][sy] = 0;

        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        int minBorderDist = Integer.MAX_VALUE;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            int d = dist[x][y];

            int border = Math.min(Math.min(x, H - 1 - x), Math.min(y, W - 1 - y));
            minBorderDist = Math.min(minBorderDist, border);

            if (d == K) continue;

            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
                if (dist[nx][ny] != -1) continue;
                if (grid[nx][ny] == '#') continue;
                dist[nx][ny] = d + 1;
                q.add(new int[]{nx, ny});
            }
        }

        // If a border cell is reachable in the first cast, answer is 1.
        // Otherwise, after reaching the closest such cell, each additional cast
        // can reduce the remaining distance to outside by at most K.
        int answer = 1 + (minBorderDist + K - 1) / K;

        System.out.println(answer);
    }
}

