    for i in range(H):
        grid.append(input_data[idx]); idx += 1

    sr, sc = 0, 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                sr, sc = i, j

    reachable = [[False]*W for _ in range(H)]

    def expand(reachable):
        # BFS: state (r, c, locks_used), minimize moves
        dist = [[[float('inf')]*(K+1) for _ in range(W)] for _ in range(H)]
        q = deque()
        for i in range(H):
            for j in range(W):
                if reachable[i][j]:
                    dist[i][j][0] = 0
                    q.append((i, j, 0, 0))
        while q:
            r, c, moves, locks = q.popleft()
            if dist[r][c][locks] < moves: continue
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<H and 0<=nc<W:
                    nm = moves+1
                    nl = locks + (1 if grid[nr][nc]=='#' else 0)
                    if nm<=K and nl<=K and dist[nr][nc][nl]>nm:
                        dist[nr][nc][nl]=nm
                        q.append((nr,nc,nm,nl))
        new_reach = [row[:] for row in reachable]
        for i in range(H):
            for j in range(W):
                if any(dist[i][j][l]<=K for l in range(K+1)):
                    new_reach[i][j]=True
        return new_reach

    reachable[sr][sc] = True
    # flood fill free cells
    q = deque([(sr,sc)])
    while q:
        r,c=q.popleft()
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not reachable[nr][nc] and grid[nr][nc]!='#':
                reachable[nr][nc]=True
                q.append((nr,nc))

    def is_escaped(reachable):
        for i in range(H):
            if reachable[i][0] or reachable[i][W-1]: return True
        for j in range(W):
            if reachable[0][j] or reachable[H-1][j]: return True
        return False

    for casts in range(H*W+1):
        if is_escaped(reachable): print(casts); return
        reachable = expand(reachable)
