#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int H, W, K;
    scanf("%d %d %d", &H, &W, &K);

    char **A = (char **)malloc(H * sizeof(char *));
    for (int i = 0; i < H; i++) {
        A[i] = (char *)malloc((W + 1) * sizeof(char));
        scanf("%s", A[i]);
    }

    int sx = -1, sy = -1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (A[i][j] == 'S') {
                sx = i;
                sy = j;
            }
        }
    }

    int N = H * W;
    int *qx = (int *)malloc(N * sizeof(int));
    int *qy = (int *)malloc(N * sizeof(int));
    int *dist = (int *)malloc(N * sizeof(int));
    char *vis = (char *)calloc(N, sizeof(char));

    int head = 0, tail = 0;
    qx[tail] = sx;
    qy[tail] = sy;
    tail++;
    vis[sx * W + sy] = 1;
    dist[sx * W + sy] = 0;

    int dx[4] = {1, -1, 0, 0};
    int dy[4] = {0, 0, 1, -1};

    int ans = 1 << 30;

    while (head < tail) {
        int x = qx[head];
        int y = qy[head];
        head++;

        int d = dist[x * W + y];
        if (d > K) continue;

        int to_border = x;
        if (H - 1 - x < to_border) to_border = H - 1 - x;
        if (y < to_border) to_border = y;
        if (W - 1 - y < to_border) to_border = W - 1 - y;

        int casts = 1 + (to_border + K - 1) / K;
        if (casts < ans) ans = casts;

        if (d == K) continue;

        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];
            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            if (A[nx][ny] == '#') continue;
            int id = nx * W + ny;
            if (vis[id]) continue;
            vis[id] = 1;
            dist[id] = d + 1;
            qx[tail] = nx;
            qy[tail] = ny;
            tail++;
        }
    }

    printf("%d\n", ans);

    for (int i = 0; i < H; i++) free(A[i]);
    free(A);
    free(qx);
    free(qy);
    free(dist);
    free(vis);

    return 0;
}
